begin;
create extension if not exists pgtap with schema extensions;
select extensions.plan(50);

select extensions.is((select count(*) from private.preplot_markets),9::bigint,'all requested markets plus Uganda are configured');
select extensions.ok(not has_table_privilege('authenticated','private.preplot_markets','SELECT'),'market configuration stays private');
select extensions.ok(not has_function_privilege('anon','public.update_preplot_country(text,text)','EXECUTE'),'country changes require authentication');
select extensions.ok(not has_function_privilege('authenticated','private.preplot_context(uuid)','EXECUTE'),'accounts cannot read others device context');
select extensions.is((select count(*) from private.preplot_windows('2030-01-11','KE','national')),2::bigint,'Kenya Friday keeps primary and backup across future years');
select extensions.is((select campaign from private.preplot_windows('2027-06-01','KE','national')),'madaraka_holiday','Kenya has Madaraka campaigns');
select extensions.is((select campaign from private.preplot_windows('2027-12-12','KE','national')),'jamhuri_holiday','Kenya has Jamhuri campaigns');
select extensions.is((select campaign from private.preplot_windows('2027-12-13','KE','national')),'jamhuri_observed_holiday','Sunday Kenya holiday has Monday observance');
select extensions.is((select campaign from private.preplot_windows('2027-04-26','TZ','national')),'union_day_holiday','Tanzania has Union Day campaigns');
select extensions.is((select campaign from private.preplot_windows('2027-07-07','TZ','national')),'saba_saba_holiday','Tanzania has Saba Saba campaigns');
select extensions.is((select count(*) from private.preplot_windows('2027-10-14','TZ','national')),0::bigint,'Nyerere remembrance suppresses campaigns');
select extensions.is((select campaign from private.preplot_windows('2027-08-06','RW','national')),'umuganura_holiday','Umuganura is the first Friday of August');
select extensions.is((select count(*) from private.preplot_windows('2027-04-09','RW','national')),0::bigint,'Rwanda mourning week suppresses weekend messages');
select extensions.is((select count(*) from private.preplot_windows('2027-04-06','RW','national')),0::bigint,'Rwanda mourning week also suppresses its eve');
select extensions.is((select campaign from private.preplot_windows('2027-09-24','ZA','national')),'heritage_day_holiday','South Africa has Heritage Day campaigns');
select extensions.is((private.preplot_holiday_for('2027-03-22','ZA','national')).mode,'suppress','South Africa observes Sunday Human Rights Day on Monday');
select extensions.is((select count(*) from private.preplot_windows('2026-11-03','ZA','national')),0::bigint,'South Africa one-off election eve is suppressed');
select extensions.is((select campaign from private.preplot_windows('2027-12-02','AE','national')),'national_day_holiday','Dubai uses UAE National Day');
select extensions.is((select count(*) from private.preplot_windows('2027-02-12','AE','national')),0::bigint,'Dubai Ramadan suppresses weekend campaigns');
select extensions.is((select count(*) from private.preplot_windows('2027-03-09','AE','national')),0::bigint,'Dubai Eid period suppresses campaigns');
select extensions.is((select campaign from private.preplot_windows('2030-08-05','GB','scotland')),'summer_bank_holiday','Scotland summer bank holiday is first Monday in August');
select extensions.is((select campaign from private.preplot_windows('2030-08-26','GB','england-and-wales')),'summer_bank_holiday','England and Wales summer bank holiday is last Monday');
select extensions.is((select count(*) from private.preplot_windows('2030-07-12','GB','northern-ireland')),0::bigint,'Northern Ireland observance suppresses a Friday');
select extensions.is((private.preplot_holiday_for('2027-12-27','GB','england-and-wales')).campaign,'christmas','official UK substitute date overrides recurrence');
select extensions.is((select campaign from private.preplot_windows('2030-11-28','US','national')),'thanksgiving_holiday','US Thanksgiving follows fourth Thursday');
select extensions.is((select campaign from private.preplot_windows('2027-07-05','US','national')),'independence_observed_holiday','US Sunday holiday observes Monday');
select extensions.is((select count(*) from private.preplot_windows('2027-05-31','US','national')),0::bigint,'US Memorial Day suppresses campaigns');
select extensions.is((select campaign from private.preplot_windows('2027-05-24','CA','national')),'victoria_day_holiday','Canada Victoria Day is Monday preceding May 25');
select extensions.is((private.preplot_holiday_for('2030-05-20','CA','national')).campaign,'victoria_day','Canada Victoria Day recurs with the weekday rather than a fixed date');
select extensions.is((select count(*) from private.preplot_windows('2027-09-30','CA','national')),0::bigint,'Canada Truth and Reconciliation Day suppresses campaigns');

insert into auth.users(id,email,raw_user_meta_data) values ('a1000000-0000-4000-8000-000000000001','country@example.test','{"display_name":"Country","age_confirmed":true}');
insert into auth.sessions(id,user_id) values ('a2000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001');
select set_config('request.jwt.claim.sub','a1000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"a1000000-0000-4000-8000-000000000001","session_id":"a2000000-0000-4000-8000-000000000001"}',true);
set local role authenticated;
select extensions.is(public.get_preplot_preferences()->>'countryCode','UG','unset country retains the launch display default');
select extensions.is(public.get_preplot_preferences()->>'countrySelected','true','new accounts use Uganda without a country selection step');
select public.register_native_push('a3000000-0000-4000-8000-000000000001','ExpoPushToken[country]','ios');
select public.update_native_push_context('a3000000-0000-4000-8000-000000000001','Africa/Nairobi');
select extensions.is(public.update_preplot_country('KE','national')->>'countryCode','KE','account can explicitly choose Kenya');
select extensions.throws_ok($$select public.update_preplot_country('XX','national')$$,'22023','Choose a supported country and calendar.','unsupported countries are rejected');
select extensions.throws_ok($$select public.update_preplot_country('GB','national')$$,'22023','Choose a supported country and calendar.','UK requires a specific nation');
reset role;
select extensions.is(private.create_due_preplot_events('2027-01-08T14:15:00Z'),1,'Kenya local-time window schedules a campaign');
select extensions.ok((select title not like '%Kampala%' and title not like '%Ofuluma%' from public.notification_events where recipient_user_id='a1000000-0000-4000-8000-000000000001'),'Kenya does not inherit Uganda city or Luganda copy');
set local role authenticated;
select public.update_preplot_country('RW','national');
select public.update_native_push_context('a3000000-0000-4000-8000-000000000001','Africa/Kigali');
reset role;
select extensions.is(private.create_due_preplot_events('2027-01-09T13:30:00Z'),1,'Rwanda Saturday schedules at UTC+2');
set local role authenticated;
select public.update_preplot_country('ZA','national');
select public.update_native_push_context('a3000000-0000-4000-8000-000000000001','Africa/Johannesburg');
reset role;
update private.preplot_preferences set sunday_enabled=true;
select extensions.is(private.create_due_preplot_events('2027-01-10T14:00:00Z'),0,'country changes do not reset the two-push cap');
delete from public.notification_events where recipient_user_id='a1000000-0000-4000-8000-000000000001';
set local role authenticated;
select public.update_preplot_country('US','national');
select public.update_native_push_context('a3000000-0000-4000-8000-000000000001','America/New_York');
reset role;
select extensions.is(private.create_due_preplot_events('2027-01-08T22:15:00Z'),1,'New York winter uses UTC-5');
delete from public.notification_events where recipient_user_id='a1000000-0000-4000-8000-000000000001';
select extensions.is(private.create_due_preplot_events('2027-07-09T21:15:00Z'),1,'New York summer uses UTC-4');
delete from public.notification_events where recipient_user_id='a1000000-0000-4000-8000-000000000001';
set local role authenticated;
select public.update_preplot_country('GB','scotland');
select public.update_native_push_context('a3000000-0000-4000-8000-000000000001','Europe/London');
reset role;
select extensions.is(private.create_due_preplot_events('2027-07-09T16:15:00Z'),1,'London summer uses UTC+1');
delete from public.notification_events where recipient_user_id='a1000000-0000-4000-8000-000000000001';
select extensions.is(private.create_due_preplot_events('2027-01-08T17:15:00Z'),1,'London winter uses UTC+0');
update private.preplot_preferences set quiet_start='16:00',quiet_end='18:00';
select extensions.ok(not private.preplot_user_eligible('a1000000-0000-4000-8000-000000000001','2027-07-09T16:15:00Z'),'quiet hours use current local timezone');
update private.preplot_preferences set quiet_start='22:00',quiet_end='08:00';
update public.native_push_subscriptions set timezone='Asia/Dubai';
select extensions.ok(not private.preplot_user_eligible('a1000000-0000-4000-8000-000000000001','2027-07-09T16:15:00Z'),'device outside selected market is suppressed without inferring a new country');
update private.preplot_markets set enabled=false where country_code='KE';
select extensions.is((select count(*) from private.preplot_windows('2030-01-11','KE','national')),0::bigint,'operator market flag disables campaigns');
select extensions.is((select count(*) from private.preplot_windows('2027-01-08','TZ','national')),2::bigint,'disabling one market leaves another active');

-- Context changes immediately discard a queued live message, without sending it.
update private.preplot_preferences set country_code='ZA',calendar_region='national',quiet_start='00:00',quiet_end='00:00:01';
update public.native_push_subscriptions set timezone='Africa/Johannesburg';
insert into public.notification_events(id,event_key,recipient_user_id,category,event_type,title,body,deep_link,expires_at)
values('a4000000-0000-4000-8000-000000000001','context-live','a1000000-0000-4000-8000-000000000001','preplot','preplot','Weekend plans?','Start a Night.','/night/new',clock_timestamp()+interval '1 hour');
insert into private.preplot_campaigns(event_id,user_id,campaign,local_day,starts_at,expires_at,country_code,calendar_region,timezone)
values('a4000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','friday_preplot',current_date,clock_timestamp()-interval '1 minute',clock_timestamp()+interval '1 hour','ZA','national','Africa/Johannesburg');
insert into public.native_notification_deliveries(event_id,subscription_id,status,attempts)
select 'a4000000-0000-4000-8000-000000000001',id,'queued',0 from public.native_push_subscriptions where user_id='a1000000-0000-4000-8000-000000000001';
set local role authenticated;
select public.update_preplot_country('TZ','national');
reset role;
select extensions.ok((select suppressed_at is not null from private.preplot_campaigns where event_id='a4000000-0000-4000-8000-000000000001'),'country change suppresses the previous campaign');
select extensions.is((select status from public.native_notification_deliveries where event_id='a4000000-0000-4000-8000-000000000001'),'discarded','country change immediately discards queued native delivery');
select extensions.ok(not private.native_notification_current(e,s),'previous-country event fails the final native check') from public.notification_events e cross join public.native_push_subscriptions s where e.id='a4000000-0000-4000-8000-000000000001' and s.user_id=e.recipient_user_id;
select * from extensions.finish();
rollback;
